-- Move the two historically fixed BlueMap polygons into the territory database.
-- No original applicant, application date or approval date is known.
-- Null actor references are restricted to these two imported records.
-- statement
ALTER TABLE territories ALTER COLUMN applicant_account_id DROP NOT NULL;
-- statement
ALTER TABLE territory_applications ALTER COLUMN submitted_by_account_id DROP NOT NULL;
-- statement
ALTER TABLE territories ADD CONSTRAINT territories_imported_applicant_only
  CHECK (applicant_account_id IS NOT NULL OR id IN ('6d91fdae-8331-4b4d-858e-000000000001'::uuid, '6d91fdae-8331-4b4d-858e-000000000002'::uuid));
-- statement
ALTER TABLE territory_applications ADD CONSTRAINT territory_applications_imported_submitter_only
  CHECK (submitted_by_account_id IS NOT NULL OR
    (id = '6d91fdae-8331-4b4d-858e-000000000101'::uuid AND territory_id = '6d91fdae-8331-4b4d-858e-000000000001'::uuid AND application_type = 'new') OR
    (id = '6d91fdae-8331-4b4d-858e-000000000102'::uuid AND territory_id = '6d91fdae-8331-4b4d-858e-000000000002'::uuid AND application_type = 'new'));
-- statement
